import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.XVqh0tHf.js";const u=JSON.parse('{"title":"Project Pitch: Sachidanand Health Care (VITALS)","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),o={name:"00b-project-pitch.md"};function r(s,e,c,d,l,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="project-pitch-sachidanand-health-care-vitals" tabindex="-1">Project Pitch: Sachidanand Health Care (VITALS) <a class="header-anchor" href="#project-pitch-sachidanand-health-care-vitals" aria-label="Permalink to &quot;Project Pitch: Sachidanand Health Care (VITALS)&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><p>&quot;I built <strong>Sachidanand Health Care (VITALS)</strong>, a full-stack smart hospital operating system that solves medical administrative fragmentation and financial opacity. Built on Express 5, Node.js, and MongoDB, it features a cinema-style visual bed allocation grid, an automated clinical decision support system that blocks contra-indicated drug combinations, a multi-tenant medical document and DICOM imaging store, Jitsi-powered remote telemedicine, and a gamified digital therapeutics engine for post-stroke rehabilitation.&quot;</p><h2 id="_2-minute-spoken-pitch" tabindex="-1">2-Minute Spoken Pitch <a class="header-anchor" href="#_2-minute-spoken-pitch" aria-label="Permalink to &quot;2-Minute Spoken Pitch&quot;">​</a></h2><p>&quot;Hospital stays are often filled with anxiety, primarily due to financial surprises, disjointed care teams, and paper-based inefficiency. A patient shouldn&#39;t have to wait four hours in an emergency room just to find out if an ICU bed is available, or face a surprise billing statement after surgery.</p><p>To fix this, I engineered VITALS as an integrated full-stack hospital ecosystem:</p><p>First, on the administrative side, I developed a visual bed allocation grid inspired by airline seating software. Wards can view, reserve, and discharge beds across General, Semi-Private, and ICU wards in real time, while our financial calculator dynamically projects surgical expenses based on insurance deductibles and room selection before admission.</p><p>Second, for clinical safety, I built an automated Clinical Decision Support System (CDSS) in <code>decisionSupportRoutes.js</code> and <code>ContraindicationRule.js</code>. When a physician prescribes a medication or orders a procedure, the engine evaluates the patient&#39;s existing allergies and active treatment plans, intercepting adverse drug interactions before orders reach the pharmacy.</p><p>Third, for diagnostics, our multi-tenant document store manages laboratory reports and MRI imaging metadata, enforcing checksum validation and virus scanning status before files can be viewed.</p><p>Finally, we closed the loop on post-discharge recovery by embedding Jitsi WebRTC video consultations and a gamified stroke rehabilitation module that turns repetitive motor exercises into an engaging digital therapy.</p><p>The backend runs on Express 5 with rigorous multi-tenant RBAC, brute-force lockout defense, and automated testing via Node&#39;s native test runner and in-memory MongoDB.&quot;</p>',11)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
